'use client'

import { useState } from 'react'
import { createProtectedPayload } from '../../lib/browser-protected-payload'

const formStyle = {
  display: 'grid',
  gap: '16px',
  marginTop: '24px',
}

const formTitleStyle = {
  margin: 0,
  color: '#10233e',
  fontSize: '24px',
  lineHeight: 1.1,
  letterSpacing: '-0.04em',
  fontWeight: 900,
}

const formTextStyle = {
  margin: '6px 0 0',
  color: 'var(--vp-text-muted)',
  fontSize: '14px',
  lineHeight: 1.6,
}

const gridStyle = {
  display: 'grid',
  gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
  gap: '14px',
}

const labelStyle = {
  display: 'grid',
  gap: '8px',
  color: '#10233e',
  fontSize: '13px',
  fontWeight: 800,
}

const inputStyle = {
  width: '100%',
  minHeight: '52px',
  borderRadius: '16px',
  border: '1px solid var(--vp-border)',
  background: '#ffffff',
  color: '#10233e',
  padding: '0 14px',
  fontSize: '15px',
  outline: 'none',
  boxSizing: 'border-box',
}

const buttonStyle = {
  width: 'fit-content',
  minHeight: '52px',
  border: 0,
  borderRadius: '16px',
  padding: '0 22px',
  background: 'linear-gradient(135deg, #2563eb 0%, #ff8c00 100%)',
  color: '#ffffff',
  fontWeight: 900,
  cursor: 'pointer',
  boxShadow: '0 16px 34px rgba(37, 99, 235, 0.2)',
}

const messageStyle = type => ({
  margin: 0,
  padding: '12px 14px',
  borderRadius: '14px',
  color: type === 'success' ? '#166534' : '#b42318',
  background: type === 'success' ? 'rgba(34, 197, 94, 0.12)' : 'rgba(244, 63, 94, 0.1)',
  border: type === 'success' ? '1px solid rgba(34, 197, 94, 0.22)' : '1px solid rgba(244, 63, 94, 0.2)',
  fontWeight: 800,
})

export default function ChangePasswordForm() {
  const [form, setForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: '',
  })
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState('')
  const [messageType, setMessageType] = useState('success')

  function handleChange(event) {
    const { name, value } = event.target
    setForm(previousForm => ({ ...previousForm, [name]: value }))
  }

  async function handleSubmit(event) {
    event.preventDefault()
    setSaving(true)
    setMessage('')

    try {
      const protectedPayload = await createProtectedPayload(form)
      const response = await fetch('/api/account/password', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ protectedPayload }),
      })
      const data = await response.json().catch(() => ({}))

      if (!response.ok) {
        throw new Error(data.error || 'Não foi possível atualizar a palavra-passe.')
      }

      setForm({ currentPassword: '', newPassword: '', confirmPassword: '' })
      setMessageType('success')
      setMessage('Palavra-passe atualizada com sucesso. Na próxima entrada usa a nova palavra-passe.')
    } catch (error) {
      setMessageType('error')
      setMessage(error.message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <form style={formStyle} onSubmit={handleSubmit}>
      <div>
        <h2 style={formTitleStyle}>Trocar palavra-passe</h2>
      </div>

      <div style={gridStyle}>
        <label style={labelStyle}>
          Palavra-passe atual
          <input
            type="password"
            name="currentPassword"
            value={form.currentPassword}
            onChange={handleChange}
            style={inputStyle}
            autoComplete="current-password"
          />
        </label>
        <label style={labelStyle}>
          Nova palavra-passe
          <input
            type="password"
            name="newPassword"
            value={form.newPassword}
            onChange={handleChange}
            style={inputStyle}
            autoComplete="new-password"
          />
        </label>
        <label style={labelStyle}>
          Confirmar nova palavra-passe
          <input
            type="password"
            name="confirmPassword"
            value={form.confirmPassword}
            onChange={handleChange}
            style={inputStyle}
            autoComplete="new-password"
          />
        </label>
      </div>

      {message && <p style={messageStyle(messageType)}>{message}</p>}

      <button type="submit" disabled={saving} style={saving ? { ...buttonStyle, opacity: 0.65, cursor: 'not-allowed' } : buttonStyle}>
        {saving ? 'A guardar...' : 'Atualizar palavra-passe'}
      </button>
    </form>
  )
}

'use client'

import { useEffect, useState } from 'react'
import {
  DEFAULT_REMINDER_SETTINGS,
  REMINDER_SETTINGS_STORAGE_KEY,
  normalizeReminderSettings,
} from '../../lib/reminder-settings.js'

const formStyle = ({ withTopBorder = true, marginTop = '24px' } = {}) => ({
  display: 'grid',
  gap: '16px',
  marginTop,
  paddingTop: withTopBorder ? '24px' : 0,
  borderTop: withTopBorder ? '1px solid var(--vp-border)' : 'none',
})

const formTitleStyle = {
  margin: 0,
  color: '#10233e',
  fontSize: '24px',
  lineHeight: 1.1,
  letterSpacing: '-0.04em',
  fontWeight: 900,
}

const formTextStyle = {
  margin: '6px 0 0',
  color: 'var(--vp-text-muted)',
  fontSize: '14px',
  lineHeight: 1.6,
}

const gridStyle = {
  display: 'grid',
  gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
  gap: '14px',
}

const labelStyle = {
  display: 'grid',
  gap: '8px',
  color: '#10233e',
  fontSize: '13px',
  fontWeight: 800,
}

const inputStyle = {
  width: '100%',
  minHeight: '52px',
  borderRadius: '16px',
  border: '1px solid var(--vp-border)',
  background: '#ffffff',
  color: '#10233e',
  padding: '0 14px',
  fontSize: '15px',
  outline: 'none',
  boxSizing: 'border-box',
}

const buttonStyle = {
  width: 'fit-content',
  minHeight: '52px',
  border: 0,
  borderRadius: '16px',
  padding: '0 22px',
  background: 'linear-gradient(135deg, #2563eb 0%, #ff8c00 100%)',
  color: '#ffffff',
  fontWeight: 900,
  cursor: 'pointer',
  boxShadow: '0 16px 34px rgba(37, 99, 235, 0.2)',
}

const messageStyle = {
  margin: 0,
  padding: '12px 14px',
  borderRadius: '14px',
  color: '#166534',
  background: 'rgba(34, 197, 94, 0.12)',
  border: '1px solid rgba(34, 197, 94, 0.22)',
  fontWeight: 800,
}

export default function NotificationSettingsForm({
  title = 'Horário das notificações',
  description = 'Define a que horas queres receber o aviso para submeter o registo diário.',
  withTopBorder = true,
  marginTop = '24px',
}) {
  const [form, setForm] = useState(DEFAULT_REMINDER_SETTINGS)
  const [message, setMessage] = useState('')

  useEffect(() => {
    try {
      const storedSettings = JSON.parse(window.localStorage.getItem(REMINDER_SETTINGS_STORAGE_KEY) || '{}')
      setForm(normalizeReminderSettings(storedSettings))
    } catch (error) {
      setForm(DEFAULT_REMINDER_SETTINGS)
    }
  }, [])

  function handleChange(event) {
    const { name, value } = event.target
    setForm(previousForm => ({ ...previousForm, [name]: value }))
    setMessage('')
  }

  function handleSubmit(event) {
    event.preventDefault()
    const normalizedSettings = normalizeReminderSettings(form)
    window.localStorage.setItem(REMINDER_SETTINGS_STORAGE_KEY, JSON.stringify(normalizedSettings))
    setForm(normalizedSettings)
    setMessage('Horário das notificações atualizado com sucesso.')
  }

  return (
    <form style={formStyle({ withTopBorder, marginTop })} onSubmit={handleSubmit}>
      <div>
        <h2 style={formTitleStyle}>{title}</h2>
        {description ? <p style={formTextStyle}>{description}</p> : null}
      </div>

      <div style={gridStyle}>
        <label style={labelStyle}>
          Durante a semana
          <input type="time" name="weekday" value={form.weekday} onChange={handleChange} style={inputStyle} />
        </label>
        <label style={labelStyle}>
          Ao sábado
          <input type="time" name="saturday" value={form.saturday} onChange={handleChange} style={inputStyle} />
        </label>
      </div>

      {message && <p style={messageStyle}>{message}</p>}

      <button type="submit" style={buttonStyle}>
        Guardar horário
      </button>
    </form>
  )
}

import { NextResponse } from 'next/server'
import { getLoginTransportPublicKey } from '../../../../lib/login-transport.js'

export const dynamic = 'force-dynamic'

export async function GET() {
  try {
    const response = NextResponse.json({ publicKey: getLoginTransportPublicKey() })
    response.headers.set('Cache-Control', 'no-store')
    return response
  } catch (error) {
    return NextResponse.json({ error: 'Protecao de login nao configurada.' }, { status: 503 })
  }
}

import { NextResponse } from 'next/server'
import { deleteChefData, getChefByIdData, updateChefData } from '../../../../lib/chefs.js'
import { readProtectedRequestJson } from '../../../../lib/login-transport.js'

function hidePassword(identity) {
  const { password, ...safeIdentity } = identity
  return safeIdentity
}

export async function GET(request, { params }) {
  try {
    const { id } = await params
    const identity = await getChefByIdData(id)

    if (!identity) {
      return NextResponse.json({ error: 'Identidade não encontrada' }, { status: 404 })
    }

    return NextResponse.json(hidePassword(identity))
  } catch (error) {
    return NextResponse.json({ error: 'Erro ao obter identidade' }, { status: 500 })
  }
}

export async function PUT(request, { params }) {
  try {
    const { id } = await params
    const body = await readProtectedRequestJson(request)
    const { personId, username, password, works } = body

    const identity = await updateChefData(id, { personId, username, password, works })

    if (!identity) {
      return NextResponse.json({ error: 'Identidade não encontrada' }, { status: 404 })
    }

    return NextResponse.json(hidePassword(identity))
  } catch (error) {
    if (error.message?.includes('protecao') || error.message?.includes('protegido')) {
      return NextResponse.json({ error: 'Pedido sensível não protegido.' }, { status: 400 })
    }

    const status =
      error.message?.includes('obrigatório') ||
      error.message?.includes('palavra-passe') ||
      error.message?.includes('carácter') ||
      error.message?.includes('bytes') ||
      error.message?.includes('Já existe') ||
      error.message?.includes('role')
        ? 400
        : error.message?.includes('não encontrada')
          ? 404
          : 500

    return NextResponse.json({ error: error.message || 'Erro ao atualizar identidade' }, { status })
  }
}

export async function DELETE(request, { params }) {
  try {
    const { id } = await params
    const deleted = await deleteChefData(id)

    if (!deleted) {
      return NextResponse.json({ error: 'Identidade não encontrada' }, { status: 404 })
    }

    return NextResponse.json({ message: 'Identidade removida com sucesso' })
  } catch (error) {
    return NextResponse.json({ error: 'Erro ao remover identidade' }, { status: 500 })
  }
}

