              value={filters.entity}
              onChange={event => handleFilterChange('entity', event.target.value)}
            />
          </div>

          <div>
            <label style={{ fontSize: '0.875rem', color: '#6b7280', display: 'block', marginBottom: '0.25rem' }}>
              Acao
            </label>
            <select
              style={inputStyle}
