                  ) : null}
                </article>
              )
            })
          )}
        </div>
      </section>

      {selectedLog ? (
        <div style={modalOverlayStyle} onClick={() => setSelectedLog(null)}>
          <div style={modalStyle} onClick={event => event.stopPropagation()}>
            <div style={actionRowStyle}>
              <div>
                <h3 style={{ margin: 0, color: '#10233e', fontSize: '1.4rem', fontWeight: 800 }}>
