                />
                <ActivitySection
                  title="Horas aprovadas"
                  events={activityGroups.approvedEvents}
                  emptyText="Ainda não existem horas aprovadas."
                />
                <ActivitySection
                  title="Notas da obra"
                  events={activityGroups.noteEvents}
                  emptyText="Ainda não existem notas registadas."
                />
              </div>
            </div>
          </section>
        )}
      </div>
    </main>
  )
}

