      { currentIdentity: null },
    )
    const dbIdentity = await createAccessIdentityDb({
      personId: payload.personId,
      role: payload.role,
      username: payload.username,
      passwordHash: payload.passwordHash,
      name: payload.name,
      legacySource: 'access_identity',
      active: true,
