export const DEFAULT_HOLDING_ID = 1
export const DEFAULT_COMPANY_ID = 1

const defaultCompanyRecord = Object.freeze({
  id: DEFAULT_COMPANY_ID,
  holdingId: DEFAULT_HOLDING_ID,
  name: 'Empresa Principal',
  slug: 'empresa-principal',
