let dailyWorkNotesService = null

function getLegacyDailyWorkNotesService() {
  if (isMysqlDataSourceEnabled()) {
    return null
  }

  if (!dailyWorkNotesService) {
    dailyWorkNotesService = new DailyWorkNotesService()
  }

  return dailyWorkNotesService
}

function upsertDailyWorkNoteMirror(noteData) {
  const legacyService = getLegacyDailyWorkNotesService()
  const normalizedNote = new DailyWorkNote(noteData)

  if (!legacyService) {
    return normalizedNote
  }

  legacyService.refresh()

  const currentIndex = legacyService.notes.findIndex(
    note => note.date === normalizedNote.date && note.workId === normalizedNote.workId,
  )

  if (currentIndex >= 0) {
    legacyService.notes[currentIndex] = normalizedNote
  } else {
    legacyService.notes.push(normalizedNote)
  }

  legacyService.save()
  return normalizedNote
}

function removeDailyWorkNotesMirror(ids = []) {
  return getLegacyDailyWorkNotesService()?.removeMany(ids) || 0
}

